TODOS = []
_id_counter = 0


def next_id():
    global _id_counter
    _id_counter += 1
    return _id_counter


def find_todo(todo_id):
    for todo in TODOS:
        if todo["id"] == todo_id:
            return todo
    return None


def handle_request(method, path, body=None):
    """Return a (status, data) tuple for the to-do API."""
    parts = [p for p in path.split("/") if p]

    if parts == ["todos"]:
        if method == "GET":
            return (200, TODOS)
        if method == "POST":
            title = (body or {}).get("title")
            if not title:
                return (400, {"error": "title is required"})
            todo = {"id": next_id(), "title": title, "done": False}
            TODOS.append(todo)
            return (201, todo)
        return (405, {"error": "method not allowed"})

    if len(parts) == 2 and parts[0] == "todos" and parts[1].isdigit():
        todo = find_todo(int(parts[1]))
        if todo is None:
            return (404, {"error": "not found"})
        if method == "GET":
            return (200, todo)
        if method == "PATCH":
            if body and "done" in body:
                todo["done"] = bool(body["done"])
            return (200, todo)
        if method == "DELETE":
            TODOS.remove(todo)
            return (204, None)
        return (405, {"error": "method not allowed"})

    return (404, {"error": "not found"})


print(handle_request("POST", "/todos", {"title": "Order brake pads"}))
print(handle_request("GET", "/todos"))

